This is a greedy simulation that schedules projects in event order.

**Approach**
- Each contributor has a free time and a skill map from skill name to level.
- Repeat until no project can be scheduled:
  - Among the unscheduled projects, try to fill the roles.
  - A project is only attempted if it is not hopeless, meaning its score at the earliest possible finish is still above zero.
  - Take the first feasible project in priority order, sorted by best-before minus duration (earliest deadline first), with ties broken by higher score.
- To keep this fast, I use rounds. In each round I iterate over the projects in priority order. For each project, I try to assign contributors greedily, then commit it if feasible. A round that commits nothing ends the loop.
- Each project is committed at most once, and the number of rounds is limited by a time check.

**Assigning a project**
- Roles are processed in order, sorted by descending required level.
- For each role, choose the contributor not already used in this project who meets the level (level ≥ required), picking the one with the smallest free time and then the smallest level.
- If no contributor meets the level, allow level = required−1 when a mentor exists. The mentor can be any already-chosen team member with the skill at ≥ required, or any contributor chosen later. To keep it simple, I do a two-pass approach: first fill all roles with full-level contributors where possible, and fill a role with a level−1 contributor only if some member of the team already has the skill at the required level.
- The contributors' levels used for the check are their current levels, which is consistent because they are updated at commit time in the order of the output.

**Timing and scheduling**
- Contributors' free times are tracked, and the start time is the maximum of the team's free times.
- Candidate search per role is a linear scan over all C contributors. That is expensive: 1e5 projects × 1e5 contributors × roles is too much.
- To bound the cost, I index contributors by skill (a vector of contributor ids per skill). For each role I scan only that skill's list, capped at a limited number of entries, plus a mentee fallback scan limited to the same cap.
- A total operation budget is enforced.

**Output order and validity**
- The output order is the commit order. Because I simulate commits in that order and the start time is the max of the free times, the scoring is identical to my simulation.
- Levels are updated at commit time, which matches the judge, since a contributor's projects run in submission order.

```cpp
#include <bits/stdc++.h>
using namespace std;
struct Pr{string name;int d,s,b;vector<pair<int,int>> r;};
int main(){
    int C,P;
    scanf("%d %d",&C,&P);
    unordered_map<string,int> sid;
    vector<string> cn(C);
    vector<unordered_map<int,int>> sk(C);
    auto gid=[&](const string&s){auto it=sid.find(s);if(it!=sid.end())return it->second;int k=sid.size();sid[s]=k;return k;};
    char b1[64],b2[64];
    for(int i=0;i<C;i++){
        int n;scanf("%s %d",b1,&n);cn[i]=b1;
        for(int j=0;j<n;j++){int l;scanf("%s %d",b2,&l);sk[i][gid(b2)]=l;}
    }
    vector<Pr> pr(P);
    for(int i=0;i<P;i++){
        int R;scanf("%s %d %d %d %d",b1,&pr[i].d,&pr[i].s,&pr[i].b,&R);
        pr[i].name=b1;
        for(int j=0;j<R;j++){int l;scanf("%s %d",b2,&l);pr[i].r.push_back({gid(b2),l});}
    }
    int S=sid.size();
    vector<vector<int>> bySk(S);
    for(int i=0;i<C;i++)for(auto&p:sk[i])bySk[p.first].push_back(i);
    vector<int> order(P);
    iota(order.begin(),order.end(),0);
    stable_sort(order.begin(),order.end(),[&](int a,int b){
        long long x=pr[a].b-pr[a].d,y=pr[b].b-pr[b].d;
        if(x!=y)return x<y;
        return pr[a].s>pr[b].s;});
    vector<long long> fr(C,0);
    vector<char> done(P,0);
    vector<int> usedMark(C,-1);
    int stamp=0;
    vector<pair<int,vector<int>>> out;
    auto lvl=[&](int c,int s){auto it=sk[c].find(s);return it==sk[c].end()?0:it->second;};
    auto st=chrono::steady_clock::now();
    bool timeUp=false;
    const int CAP=300;
    for(int round=0;round<50&&!timeUp;round++){
        int committed=0;
        for(int pi:order){
            if(done[pi])continue;
            if(chrono::duration<double>(chrono::steady_clock::now()-st).count()>8){timeUp=true;break;}
            Pr&p=pr[pi];
            int R=p.r.size();
            stamp++;
            vector<int> asg(R,-1);
            vector<int> idx(R);
            iota(idx.begin(),idx.end(),0);
            sort(idx.begin(),idx.end(),[&](int a,int b){return p.r[a].second>p.r[b].second;});
            bool ok=true;
            vector<int> team;
            long long bestStart=0;
            // pass 1: full-level
            for(int k:idx){
                int s=p.r[k].first,l=p.r[k].second;
                int best=-1;long long bk=0;int cnt=0;
                for(int c:bySk[s]){
                    if(usedMark[c]==stamp)continue;
                    int lv=lvl(c,s);
                    if(lv<l)continue;
                    long long key=max(fr[c],0LL)*20+(lv-l);
                    if(best<0||key<bk){best=c;bk=key;}
                    if(++cnt>=CAP)break;
                }
                if(best>=0){asg[k]=best;usedMark[best]=stamp;team.push_back(best);}
            }
            // pass 2: mentee
            for(int k:idx){
                if(asg[k]>=0)continue;
                int s=p.r[k].first,l=p.r[k].second;
                bool has=false;
                for(int c:team)if(lvl(c,s)>=l){has=true;break;}
                if(!has||l==0){ok=false;break;}
                int best=-1;long long bk=0;int cnt=0;
                if(l-1==0){
                    // anyone with level 0: scan contributors, capped
                    for(int c=0;c<C&&cnt<CAP*3;c++){
                        if(usedMark[c]==stamp)continue;
                        cnt++;
                        long long key=fr[c];
                        if(best<0||key<bk){best=c;bk=key;}
                    }
                } else {
                    for(int c:bySk[s]){
                        if(usedMark[c]==stamp)continue;
                        if(lvl(c,s)!=l-1)continue;
                        long long key=fr[c];
                        if(best<0||key<bk){best=c;bk=key;}
                        if(++cnt>=CAP)break;
                    }
                }
                if(best<0){ok=false;break;}
                asg[k]=best;usedMark[best]=stamp;team.push_back(best);
            }
            if(!ok)continue;
            for(int c:team)bestStart=max(bestStart,fr[c]);
            long long fin=bestStart+p.d;
            if(fin>=p.b+p.s)continue; // zero score
            // commit
            for(int k=0;k<R;k++){
                int c=asg[k],s=p.r[k].first,l=p.r[k].second;
                if(lvl(c,s)<=l)sk[c][s]=lvl(c,s)+1;
                if(lvl(c,s)==1&&bySk[s].size()>=0){
                    // newly gained skill: register
                    if(find(bySk[s].begin(),bySk[s].end(),c)==bySk[s].end()&&bySk[s].size()<2000000)bySk[s].push_back(c);
                }
                fr[c]=fin;
            }
            done[pi]=1;committed++;
            out.push_back({pi,asg});
        }
        if(!committed)break;
    }
    printf("%d\n",(int)out.size());
    for(auto&o:out){
        printf("%s\n",pr[o.first].name.c_str());
        for(size_t i=0;i<o.second.size();i++)printf("%s%s",i?" ":"",cn[o.second[i]].c_str());
        printf("\n");
    }
}
```

**Known weaknesses**
- The find on `bySk[s]` when a skill is newly gained can be slow for large lists. It runs only when the level becomes exactly 1, so it is bounded by the number of new skills gained.
- A contributor with level 0 in a skill who is promoted to level 1 and is already in the list is handled correctly by the find check.
